#!/bin/bash
# auto_merge.sh — Merge PRs that have no conflicts and are safe to land
# Generated by triage on 2026-07-28
# Usage: bash auto_merge.sh [--dry-run]

set -euo pipefail

DRY_RUN="${1:---no-dry-run}"
# Historical target-repo automation. This script must not touch an unpushed
# sibling checkout unless the operator explicitly authorizes that target and
# confirms it is clean. Prefer gh/remote refs and a localized state worktree.
REPO_DIR="${REPO_DIR:?Set REPO_DIR to an explicitly authorized clean target checkout}"
JULES_SCRIPTS_DIR="${JULES_SCRIPTS_DIR:-$(cd "$(dirname "$0")/../.." && pwd)}"

merge_pr() {
    local pr_number="$1"
    local title="$2"
    local branch="$3"
    local base="$4"

    echo "========================================"
    echo "MERGING PR #${pr_number}: ${title}"
    echo "  head: ${branch} → base: ${base}"
    echo "========================================"

    if [ "$DRY_RUN" = "--dry-run" ]; then
        echo "[DRY-RUN] Would merge PR #${pr_number}"
        return 0
    fi

    cd "$REPO_DIR"

    # Fetch and checkout base
    git fetch origin "$base"
    git checkout "$base"
    git pull origin "$base"

    # Fetch and merge the PR branch
    git fetch origin "$branch"
    git checkout -B "merge-pr-${pr_number}" "$base"
    git merge --no-ff "origin/${branch}" -m "Merge PR #${pr_number}: ${title}"

    # Run checks
    echo "Running validation..."
    if [ -f "package.json" ]; then
        npm run lint 2>/dev/null || echo "WARN: lint had issues"
        npm run typecheck 2>/dev/null || echo "WARN: typecheck had issues"
    fi
    if [ -f "pyproject.toml" ]; then
        python -m pytest tests/ -x -q 2>/dev/null || echo "WARN: tests had issues"
    fi

    # Push
    git push origin "merge-pr-${pr_number}"

    # Create PR back to base (or merge directly via gh)
    gh pr merge "$pr_number" --merge --subject "Auto-merge: ${title}" --body "Auto-merged by triage script on 2026-07-28"
}

# ──────────────────────────────────────────────
# AUTO-MERGE PRs (no conflicts, automerge label)
# ──────────────────────────────────────────────

merge_pr 320 \
    "🛡️ Sentinel: Fix Missing Import in Auth Module" \
    "sentinel-auth-fix-7484697449494974594" \
    "main"

merge_pr 317 \
    "⚡ Bolt: Optimize SmartFilterManager cache invalidation" \
    "bolt-smart-filter-opt-9777167562317481091" \
    "main"

merge_pr 322 \
    "⚡ Bolt: Fix SmartFilterManager caching crash and optimize performance" \
    "bolt-enhanced-caching-fix-15189319414508702031" \
    "main"

merge_pr 724 \
    "chore(deps): bump the npm-minor group with 36 updates" \
    "dependabot/npm_and_yarn/client/npm-minor-ad8e8ffff0" \
    "main"

echo ""
echo "✅ All auto-merge PRs processed."